                                          input logic [7:0] modrm);
    v35_fmt_of = v35_fmt_asm(opcode, page,
                             (page == 2'd1) ? v35_dec_ext(opcode) : v35_dec_native(opcode),
                             modrm);
  endfunction
  function automatic v35_fmt_t v35_fmt_asm(input logic [7:0] opcode, input logic [1:0] page,
                                           input v35_dec_t d, input logic [7:0] modrm);
    v35_grp_t g;
    v35_half_t h;
    v35_fmt_t f;
    logic hm;
    logic [1:0] md;
    logic [2:0] rf, rm;
    hm = (page == 2'd2) ? 1'b0 : d.has_modrm;
    md = hm ? modrm[7:6] : 2'd0;
    rf = hm ? modrm[5:3] : 3'd0;
    rm = hm ? modrm[2:0] : 3'd0;
    if (d.grp_v) g = v35_dec_grp(d.gidx, rf);
    else begin
      g.hr = d.hr;
      g.hm = d.hm;
    end
    h = (hm && md != 2'd3) ? g.hm : g.hr;
    if (page == 2'd2 && !h.strop) h = '0;
    f = '0;
    f.page = page;
    f.esc = (page == 2'd0) ? d.esc : 2'd0;
    f.seg = d.seg;
    f.repc = d.repc;
    f.rep = (page == 2'd2);
    f.has_modrm = hm;
    f.md = md;
    f.rfield = rf;
    f.rm = rm;
    f.disp = (hm && md == 2'd1) ? 2'd1
           : (hm && (md == 2'd2 || (md == 2'd0 && rm == 3'd6))) ? 2'd2 : 2'd0;
    f.len = 3'd1 + {2'd0, page != 2'd0} + {2'd0, hm} + {1'b0, f.disp} + h.tail;
    f.valid = h.v;
    f.cls = h.cls;
    f.tail = h.tail;
    f.immb = h.immb;
    f.w = h.w;
    f.mem = h.mem;
    f.ea_mode = (h.mem && hm) ? v35_ea_mode(md, rm) : h.mem ? h.eafix : 3'd0;
    f.bix16 = hm && md == 2'd2 && !rm[2];
    f.ccode = h.cond ? opcode[3:0] : 4'd0;
    f.sgn = h.sgn;
    f.grp = h.grp;
    f.fixed_alu = h.fixed_alu;
    f.shift = h.shift;
    f.cl_shift = h.cl_shift;
    f.nowrite = h.nowrite;
    f.swap = h.swap;
    f.dbit_v = h.dbit_v;
    f.dbit = h.dbit;
    f.cond = h.cond;
    f.count_byte = h.count_byte;
    f.cl_count = h.cl_count;
    f.modrm_op = h.modrm_op;
    f.bus = h.bus;
    f.port = h.port;
    f.sreg = h.sreg;
    f.interlock = h.interlock;
    f.regonly = h.regonly;
    f.port_io = h.port_io;
    f.one_reg = h.one_reg;
    f.long1 = h.long1;
    f.unit_reg = h.unit_reg;
    f.unit_mem = h.unit_mem;
    f.fixed_grp = h.fixed_grp;
    f.imm16_reg = h.imm16_reg;
    f.modrm_pre = h.modrm_pre;
    f.far_xfer = h.far_xfer;
    f.xfer_mem = h.xfer_mem;
    f.imm1_mem = h.imm1_mem;
    f.grp_rmw = h.grp_rmw;
    f.page_reg = h.page_reg;
    f.page_mem = h.page_mem;
    f.test1m = h.test1m;
    f.mul_imm = h.mul_imm;
    f.lea = h.lea;
    f.dbnz = h.dbnz;
    f.dbnz_z = h.dbnz_z;
    f.xfer = h.xfer;
    f.dw_count = h.dw_count;
    f.strop = h.strop;
    f.bcd = h.bcd;
    f.bf = h.bf;
    f.ro = h.ro;
    f.rmw = h.rmw;
    f.breg = h.breg;
    f.idle1 = h.idle1;
    f.tsel = h.tsel;
    f.zpol = h.zpol;
    f.xshort = h.xshort;
    f.rot4r = h.rot4r;
    f.bit1r = h.bit1r;
    f.pmt = h.pmt;
    f.pgb2b = h.pgb2b;
    f.pcl = h.pcl;
    f.xop = h.xop;
    f.aop = h.aop;
    f.opa = h.opa;
    f.opb = h.opb;
    f.wd = h.wd;
    f.nwr = h.nwr;
    f.sx = h.sx;
    f.stk = h.stk;
    v35_fmt_asm = f;
  endfunction

  // The template a started form runs (v35_tmpl_sel, v35_ucode_tbl.svh).
  function automatic logic [8:0] v35_tmpl_of(input v35_fmt_t f, input v35_run_t r);
    v35_tmpl_of = v35_tmpl_sel(f, r);
  endfunction

endpackage
